const $=s=>document.querySelector(s);const key='earth-online-v1';let state={wishes:[],memories:[],evening:false};let storageOK=true;try{const saved=JSON.parse(localStorage.getItem(key)||'null');if(saved&&Array.isArray(saved.wishes)&&Array.isArray(saved.memories))state={...state,...saved}}catch{storageOK=false}
const proposals=[{id:'walk',tag:'自然',title:'找一条没走过的小路',desc:'熟悉的街角转个弯，也许就是一场小小的旅行。',detail:'有一天想出门时，给熟悉的路线留一个不同的转弯。也可以先看看地图，把好奇的地方存起来。选择安全、方便抵达的地方就好。',trace:'一条向外延伸的小路',color:'#dce4cf',art:'path'},{id:'food',tag:'日常',title:'把周末过成早餐的味道',desc:'一碗热汤，一块面包。给自己留一顿慢慢吃的饭。',detail:'可以去一直想尝试的小店，也可以在家吃熟悉的早餐。不用精致摆盘，只要是你想吃的。',trace:'小屋旁的一张野餐垫',color:'#eee0cd',art:'food'},{id:'draw',tag:'创作',title:'留住一片喜欢的天空',desc:'拍下来，画下来，或者只是多看一会儿。',detail:'你愿意时，看看窗外的天空。用照片、几个字或简单线条留下它。不必拍得漂亮，也不必分享。',trace:'树下的一块小画板',color:'#dce6e7',art:'sky'},{id:'plant',tag:'自然',title:'认识一位植物邻居',desc:'每天路过的那棵树，也许有个好听的名字。',detail:'从附近常见的一株植物开始。可以观察叶子，也可以查查名字。保持原处，不采摘也能认识它。',trace:'屋边的一盆新绿',color:'#dfe5cd',art:'plant'},{id:'letter',tag:'日常',title:'和想念的人吃顿饭',desc:'不需要节日，一个普通的晚上就很好。',detail:'想到某个人时，可以问问对方哪天有空。还没约上也没关系，这份期待可以慢慢留着。',trace:'庭院里的一盏小灯',color:'#e9dccc',art:'food'},{id:'sound',tag:'创作',title:'给这个季节选一首歌',desc:'以后再听到它，会想起现在的自己。',detail:'选一首此刻喜欢的歌，把歌名记下来。你也可以写写，当时是在路上，还是在房间里。',trace:'小屋窗边的一枚风铃',color:'#dde1d7',art:'sky'}];
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function uid(){return Date.now().toString(36)+Math.random().toString(36).slice(2,7)}function save(){try{if(window.EarthAccount)window.EarthAccount.save(state);else localStorage.setItem(key,JSON.stringify(state));storageOK=true}catch{storageOK=false;toast('浏览器暂时无法保存，关闭后记录可能丢失。')}render()}let timer;function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(timer);timer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}function modal(html){$('#modal-content').innerHTML=html;if(!$('#modal').open)$('#modal').showModal()}$('.close').onclick=()=>$('#modal').close();$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const b=e.target.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)e.target.close()}});
function go(page){if(!['world','club','wishes','memories'].includes(page))page='world';document.querySelectorAll('.page').forEach(p=>p.hidden=p.id!==page);document.querySelectorAll('nav button').forEach(b=>{b.classList.toggle('active',b.dataset.page===page);if(b.dataset.page===page)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});if(location.hash!=='#'+page)history.replaceState(null,'','#'+page);window.scrollTo({top:0,behavior:'instant'})}document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>go(b.dataset.page));document.querySelectorAll('[data-goto]').forEach(b=>b.onclick=()=>go(b.dataset.goto));window.addEventListener('hashchange',()=>go(location.hash.slice(1)));
function art(p){let shape=p.art==='path'?'<path d="M0 112Q85 38 166 100T340 74V180H0" fill="#a6b693"/><path d="M100 180Q230 106 156 103T210 65" stroke="#f3ebd2" stroke-width="18" fill="none"/><path d="M62 99V36M265 109V52" stroke="#7c8c64" stroke-width="5"/><ellipse cx="62" cy="40" rx="24" ry="35" fill="#809c71"/><ellipse cx="265" cy="49" rx="27" ry="33" fill="#91a67b"/>':p.art==='food'?'<ellipse cx="168" cy="125" rx="91" ry="20" fill="#d7c8af"/><ellipse cx="144" cy="105" rx="55" ry="24" fill="#f8f1e1"/><path d="M105 101q20-49 52-14l17 23-66 5Z" fill="#c59460"/><path d="M205 74h35v35q-15 22-35 0Z" fill="#f9f4e4"/><path d="M240 80q28 0 0 22" stroke="#f9f4e4" stroke-width="7" fill="none"/><path d="M217 60q-9-12 1-21" stroke="#fff9" stroke-width="3" fill="none"/>':p.art==='plant'?'<path d="M144 101h52l-8 43h-36Z" fill="#bc9274"/><path d="M170 104V44" stroke="#718b62" stroke-width="4"/><ellipse cx="155" cy="64" rx="21" ry="10" transform="rotate(30 155 64)" fill="#8fa577"/><ellipse cx="186" cy="83" rx="22" ry="10" transform="rotate(-25 186 83)" fill="#9ab383"/>':'<circle cx="235" cy="47" r="23" fill="#faf1cc"/><path d="M0 131Q80 90 155 119T340 97V180H0" fill="#9fb6a3"/><path d="M0 153Q90 110 184 150T340 120V180H0" fill="#819b87"/><g fill="#fff9"><ellipse cx="115" cy="60" rx="44" ry="10"/><ellipse cx="92" cy="52" rx="22" ry="15"/></g>';return `<svg viewBox="0 0 340 180" aria-hidden="true"><rect width="340" height="180" fill="${p.color}"/>${shape}</svg>`}
function card(p){const has=state.wishes.some(w=>w.source===p.id);return `<article class="card"><div class="card-art" style="background:${p.color}">${art(p)}</div><div class="card-body"><span class="card-tag">${p.tag} · 随时都可以</span><h3>${p.title}</h3><p>${p.desc}</p><div class="card-action"><button data-detail="${p.id}">看看这个提案 ↗</button><span>${has?'♡ 已放进期待':'慢慢来'}</span></div></div></article>`}let filter='全部';function renderCards(){let items=proposals.filter(p=>filter==='全部'||p.tag===filter);$('#club-cards').innerHTML=items.map(card).join('');let first=proposals.slice(0,3);const recent=state.memories.find(m=>m.source);if(recent){const source=proposals.find(p=>p.id===recent.source);if(source){const related=proposals.find(p=>p.tag===source.tag&&p.id!==source.id);if(related)first=[related,...proposals.filter(p=>p.id!==related.id).slice(0,2)]}}$('#home-cards').innerHTML=first.map(card).join('');document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>detail(b.dataset.detail))}
function detail(id){const p=proposals.find(p=>p.id===id);const has=state.wishes.some(w=>w.source===id);modal(`<p class="eyebrow">协会生活提案 · ${p.tag}</p><h2>${p.title}</h2><div class="card-art" style="border-radius:10px">${art(p)}</div><p>${p.detail}</p><p class="footnote">心动时收藏，小岛会添上${p.trace}。体验后可以留下记录，不需要打卡。</p><div class="modal-actions"><button class="primary" id="collect">${has?'已在我的期待里':'♡ 哪天想试试'}</button><button class="text-button" id="experienced">我已经体验过了</button></div>`);$('#collect').onclick=()=>{if(!has){state.wishes.unshift({id:uid(),title:p.title,date:'',source:id});save();toast('期待收好了，小岛也多了一点变化。')}$('#modal').close()};$('#experienced').onclick=()=>memoryForm(p.title,id)}
function wishForm(){modal('<p class="eyebrow">A LITTLE ANTICIPATION</p><h2>最近，有什么让你期待？</h2><form id="wish-form"><label>我期待着<input name="title" required maxlength="80" placeholder="比如，周末去吃那家面"></label><label>日子（可以不选）<input name="date" type="date"></label><p class="footnote">没有截止，也不会因时间过去而变成逾期。</p><button class="primary" type="submit">放进我的期待 ♡</button></form>');$('#wish-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);const title=String(f.get('title')).trim();if(!title){toast('可以写下几个字，再保存。');return}state.wishes.unshift({id:uid(),title,date:f.get('date')});save();$('#modal').close();toast('给未来留了一个小小的盼头。')}}
function memoryForm(title='',source='',wishId=''){modal(`<p class="eyebrow">A MOMENT WORTH KEEPING</p><h2>留下一件小事</h2><form id="memory-form"><label>发生了什么<input name="title" required maxlength="80" value="${esc(title)}" placeholder="今天吃到了一碗很好吃的面"></label><label>想多记一点吗（选填）<textarea name="note" rows="3" maxlength="1000" placeholder="几个字也很好。"></textarea></label><button class="primary" type="submit">留在我的世界里</button></form>`);$('#memory-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);const title=String(f.get('title')).trim();if(!title)return;state.memories.unshift({id:uid(),title,note:f.get('note'),source,date:new Date().toLocaleDateString('zh-CN')});if(wishId)state.wishes=state.wishes.filter(w=>w.id!==wishId);save();$('#modal').close();toast('这个时刻，留在这里了。')}}
function removeEntry(kind,id){modal('<h2>要移走这条记录吗？</h2><p>其他期待和足迹会保留。</p><div class="modal-actions"><button class="primary" id="confirm-remove">移走这条</button><button id="cancel-remove">先留着</button></div>');$('#cancel-remove').onclick=()=>$('#modal').close();$('#confirm-remove').onclick=()=>{state[kind]=state[kind].filter(x=>x.id!==id);save();$('#modal').close();toast('已移走。')}}
function render(){renderCards();$('#wish-count').textContent=state.wishes.length;$('#wish-list').innerHTML=state.wishes.length?state.wishes.map(w=>`<article class="entry"><div><span class="card-tag">♡ ${esc(w.date||'某个想出发的日子')}</span><h3>${esc(w.title)}</h3></div><div class="entry-actions"><button data-lived="${w.id}">它发生了</button><button data-remove-wish="${w.id}" aria-label="移走期待：${esc(w.title)}">移走</button></div></article>`).join(''):'<div class="empty"><b>给未来，留一点空位。</b><p>可以写下自己的盼头，<br>也可以去协会看看哪些提案让你心动。</p><button class="text-button" id="empty-club">去协会逛逛 ↗</button></div>';$('#memory-list').innerHTML=state.memories.length?state.memories.map(m=>`<article class="entry"><div><span class="card-tag">${esc(m.date)}</span><h3>${esc(m.title)}</h3><p>${esc(m.note||'')}</p></div><div class="entry-actions"><button data-remove-memory="${m.id}" aria-label="移走足迹：${esc(m.title)}">移走</button></div></article>`).join(''):'<div class="empty"><b>生活的痕迹，会慢慢留下。</b><p>不用提前接任务。<br>刚刚发生的一件小事，也值得留在这里。</p></div>';document.querySelectorAll('[data-lived]').forEach(b=>b.onclick=()=>{const w=state.wishes.find(w=>w.id===b.dataset.lived);memoryForm(w.title,w.source,w.id)});document.querySelectorAll('[data-remove-wish]').forEach(b=>b.onclick=()=>removeEntry('wishes',b.dataset.removeWish));document.querySelectorAll('[data-remove-memory]').forEach(b=>b.onclick=()=>removeEntry('memories',b.dataset.removeMemory));if($('#empty-club'))$('#empty-club').onclick=()=>go('club');$('.world-scene').classList.toggle('evening',state.evening);$('#theme').innerHTML=state.evening?'☾ 傍晚 <span>⌄</span>':'☀ 晴日 <span>⌄</span>';let extra='';const sources=new Set(state.memories.map(x=>x.source));if(sources.has('walk'))extra+='<path d="M310 315q-60 25-75-10" fill="none" stroke="#ede6c8" stroke-width="15" stroke-linecap="round"/>';if(sources.has('food'))extra+='<path d="m453 313 45 12-30 17-44-12Z" fill="#bc8d79"/><ellipse cx="466" cy="325" rx="9" ry="4" fill="#f3e8cd"/>';if(sources.has('draw'))extra+='<path d="m332 285 18-43 19 47" fill="none" stroke="#8c7957" stroke-width="4"/><path d="m329 245 31 3v24l-31-3Z" fill="#f6ecd3"/><path d="m330 262 13-8 16 13" fill="#a0b5a5"/>';if(sources.has('plant'))extra+='<path d="M508 274h21l-4 17h-13Z" fill="#b78d6e"/><path d="M519 275v-22" stroke="#779364" stroke-width="4"/><ellipse cx="525" cy="257" rx="10" ry="5" fill="#7e9c6c"/>';if(sources.has('letter'))extra+='<path d="M560 299v-37" stroke="#827555" stroke-width="4"/><circle cx="560" cy="260" r="9" fill="#f8dda0"/>';if(sources.has('sound'))extra+='<path d="M410 241v15m-6-6h12" stroke="#c69f63" stroke-width="3"/>';state.memories.slice(0,12).forEach((m,i)=>{extra+=`<circle cx="${345+i*10}" cy="${326+(i%3)*5}" r="3" fill="#eecfa2"/>`});$('#world-extra').innerHTML=extra;$('#storage-info').textContent=storageOK?'记录保存在此浏览器':'保存不可用 · 请勿关闭页面';if(storageOK)window.EarthAccount?.updateStatus()}
$('#new-wish').onclick=$('#add-wish').onclick=wishForm;$('#add-memory').onclick=()=>memoryForm();$('#theme').onclick=$('#scene-change').onclick=()=>{state.evening=!state.evening;save()};$('#filters').onclick=e=>{const b=e.target.closest('[data-filter]');if(!b)return;filter=b.dataset.filter;$('#filters').querySelectorAll('button').forEach(x=>x.classList.toggle('selected',x===b));renderCards()};$('#home-info').onclick=()=>modal('<h2>这是你的小小世界。</h2><p>收藏生活提案，会为小岛添上对应的物件。留下经历，花园里会多一朵小花。</p><p>随时可以换一种光线。离开多久，这里都不会荒芜。</p>');$('#about').onclick=()=>modal('<p class="eyebrow">EARTH ONLINE · 交互设计原型</p><h2>让日子有所期待。</h2><p>这里有一些可以尝试的事，也有属于你的盼头。协会没有 NPC，提案没有期限；什么时候出发，由你决定。</p><p>当前版本验证个人世界、生活提案、期待和足迹之间的关系。邮箱登录与同步须在云端配置完成后启用。真实季节更新与社区尚未接入。</p>');$('#storage-info').onclick=()=>modal('<h2>关于你的记录</h2><p>期待与足迹只保存在当前设备的当前浏览器，不上传服务器。清除浏览器数据可能丢失记录，手机和电脑暂不互通。</p><p>当前是可交互原型，正式版本需要增加账户同步、备份与数据导出。</p>');$('#date').textContent=new Date().toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'})+' · 地球上的一天';render();go(location.hash.slice(1));

window.addEventListener('earth-world-loaded',e=>{state=WorldCore.validate(e.detail);render();});
window.addEventListener('earth-notice',e=>toast(e.detail));
